actions.script:
const started = ec.service.sync().name('org.moqui.maps.GeoDataServices.start#GeoDataImport').parameters({dataSetId: dataSetId || null,
    countryGeoId: context.countryGeoId || null, file: context.file || null, force: context.force === 'Y' || context.force === 'true',
    everyCountry: context.everyCountry === 'Y'}).call() || {}
if (!ec.message.hasError()) ec.message.addMessage(!started.jobRunId ? ec.l10n.localize('The import did not start: see its run below.')
    : started.queueId ? ec.resource.expand(ec.l10n.localize('Every country of ${id} is queued: ${count} imports, one after another in the background; you are notified as each ends.'), '',
        {id: dataSetId, count: started.countryCount})
    : ec.resource.expand(ec.l10n.localize('Import ${id} started in the background: you are notified when it ends.'), '', {id: started.geoDataImportId}),
    started.jobRunId ? 'success' : 'warning')

const set = ec.entity.find('moqui.maps.GeoDataSet').condition('dataSetId', String(dataSetId || '')).useCache(true).disableAuthz().one()
setFound = !!set
operatorFile = !!set && !set.urlTemplate
needsCountry = !!set && !set.coverageGeoId && (set.perCountry === 'Y' || operatorFile)
const geoData = ec.resource.script('component://framework/service/org/moqui/maps/GeoData.js')
countryOptions = needsCountry ? geoData.execute('countryOptions', {dataSetId: set.dataSetId}).countryOptions : []
// every country, as a queue of runs: a set downloaded a country at a time
estimate = needsCountry && !operatorFile ? geoData.execute('everyCountryEstimate', {dataSetId: set.dataSetId}) : {countryCount: 0}
everyCountryOffered = estimate.countryCount > 1
introText = !set ? '' : operatorFile
    ? ec.l10n.localize('A CSV with a header: country, code, place, admin1, admin2, latitude, longitude, precision (postal, place, street or address). Its rows are for the country you choose; a code it no longer has is retired in that country only.')
    : needsCountry ? ec.l10n.localize('Downloads the data set for one country and loads it in the background. Import each country you need, or every country below.')
    : ec.l10n.localize('Downloads the data set and loads it in the background. A source that has not changed since the edition in use ends as current.')
